"""Editorial systems and scientific browser-local demonstrations."""
import hashlib,html,json
from pathlib import Path
ROOT=Path(__file__).parent
D=json.loads((ROOT/'ultimate.json').read_text())
TEAM=json.loads((ROOT/'team.json').read_text())
SLUGS=['novalis-os','biladi','code32']
def esc(v):return html.escape(str(v),quote=True)
def version(name):return hashlib.sha256((ROOT/'assets'/name).read_bytes()).hexdigest()[:10]
def options(values):return ''.join(f'<option value="{i}">{esc(v)}</option>' for i,v in enumerate(values))
def graph(t):
 positions=[(16,20),(50,30),(84,20),(16,67),(50,78),(84,67),(50,53)]
 paths=''.join(f'<path d="M {positions[a][0]} {positions[a][1]} L {positions[b][0]} {positions[b][1]}"/>' for a,b in [(0,1),(1,2),(1,3),(1,4),(2,5),(2,6),(6,5),(3,4),(4,5)])
 selectors='<fieldset class="graph-profiles"><legend>'+esc(t['context_labels'][0])+'</legend>'+''.join(f'<button type="button" data-studio-profile="{i}" aria-pressed="{str(i==0).lower()}">{esc(label)}</button>' for i,label in enumerate([t['sectors'][0],t['sectors'][1],t['graph_nodes'][2]]))+'</fieldset>'
 nodes=''.join(f'<button class="graph-node graph-node-{i}" type="button" data-graph-node="{i}" style="--x:{x}%;--y:{y}%" aria-pressed="{str(i==1).lower()}"><span>0{i+1} / {esc(t["graph_nodes"][i])}</span><strong data-graph-label="{i}">{esc(t["graph_scenarios"][0][i])}</strong></button>' for i,(x,y) in enumerate(positions))
 return f'<div class="signature-graph"><div class="graph-bar"><span>NOVALIS / SYSTEM 01</span><span>{esc(t["graph_title"])}</span></div><h2 id="system-pain">{esc(t["graph_title"])}</h2>{selectors}<div class="graph-map"><svg viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true">{paths}</svg>{nodes}</div><div class="graph-explanation"><span id="graph-selected">{esc(t["graph_nodes"][1])}</span><p id="graph-description">{esc(t["graph_descriptions"][1])}</p><small>{esc(t["graph_note"])}</small></div></div>'
def lab(t):
 e=lambda k:esc(t[k]);br=lambda k:e(k).replace('\n','<br>')
 tabs=''.join(f'<button type="button" role="tab" id="play-tab-{i}" data-play-tab="{i}" aria-selected="{str(i==0).lower()}" aria-controls="play-panel-{i}" tabindex="{0 if i==0 else -1}"><span>0{i+1}</span>{esc(v)}</button>' for i,v in enumerate(t['lab_tabs']))
 tools=''.join(f'<button type="button" data-play-tool="{i}" aria-pressed="{str(i==0).lower()}"><i aria-hidden="true">{["●","◆","＋"][i]}</i>{esc(v)}</button>' for i,v in enumerate(t['tools']))
 controls=f'<div class="play-controls"><label for="play-dataset">{e("dataset_label")}<select id="play-dataset">'+''.join(f'<option value="{v}">{esc(t["datasets"][i])}</option>' for i,v in enumerate(['circles','xor','moons','spirals']))+f'</select></label><label for="play-k">{e("neighbors")}<select id="play-k"><option>1</option><option selected>3</option><option>7</option><option>9</option></select></label></div>'
 maphtml=f'''<div class="play-map-wrapper"><canvas id="play-canvas" width="720" height="480" tabindex="0" aria-label="{e('canvas_label')}" aria-describedby="play-instruction play-keyboard">{e('fallback')}</canvas><div class="map-axis" aria-hidden="true"><span>X / −1 → 1</span><span>Y / −1 → 1</span></div></div><p id="play-keyboard" class="play-note">{e('keyboard')}</p>'''
 keyboard=f'<details class="play-coordinate"><summary>{e("place")}</summary><label for="play-x">X<input id="play-x" type="range" min="0" max="100" value="50" step="5"></label><label for="play-y">Y<input id="play-y" type="range" min="0" max="100" value="50" step="5"></label><button type="button" id="play-place">{e("place")}</button></details>'
 actions=f'<div class="play-actions"><button class="button" type="button" id="play-hint">{e("add_hint")} +</button><button type="button" id="play-undo">{e("undo")} ↶</button><button type="button" id="play-reset">{e("reset")} ↺</button></div><div class="play-small-actions"><button id="play-reveal" type="button" aria-pressed="false">{e("reveal")}</button><button id="play-export" type="button">{e("export")} ↓</button><button id="play-share" type="button">{e("share")} ↗</button></div>'
 scientific=f'''<div class="play-score"><span>{e('score')}</span><div><output id="play-score">—</output><span>%</span></div><progress id="play-goal" max="100" value="0" aria-label="{e('score')}"></progress><p><span id="play-correct">—</span> / 128 · {e('correct')}</p></div><div class="play-stats"><span><strong id="play-examples">12</strong> {e('examples')}</span><span>{e('target')} <strong id="play-target">90 %</strong></span></div><p id="play-record" class="play-note"></p><p id="play-mission" role="status" aria-live="polite">{e('goal_work')}</p><details class="play-explain" open><summary>{e('explain')}</summary><p id="play-probe">{e('probe_help')}</p><ol id="play-neighbors"></ol><p id="play-vote"></p></details><p id="play-status" class="play-note" role="status"></p>{keyboard}'''
 optimize=f'''<div class="opt-story"><p class="eyebrow">N / OPTIMIZATION</p><h3>{e('opt_title')}</h3><p>{e('opt_copy')}</p><label for="opt-capacity">{e('capacity')} <output id="opt-capacity-value">10</output><input id="opt-capacity" type="range" min="0" max="20" value="10"></label><label for="opt-priority">{e('priority')}<select id="opt-priority">{options(t['priorities'])}</select></label></div><div class="opt-results"><div id="opt-items"></div><div class="opt-comparison"><article><span>{e('opt_before')}</span><output id="opt-baseline">—</output></article><article><span>{e('opt_after')}</span><output id="opt-best">—</output></article></div><p id="opt-details" role="status"></p><p class="play-note">{e('opt_note')}</p></div>'''
 document=f'''<div class="doc-story"><p class="eyebrow">N / DOCUMENT INTELLIGENCE</p><h3>{e('doc_title')}</h3><p>{e('doc_copy')}</p><label for="doc-input">{e('doc_label')}<textarea id="doc-input" rows="7" maxlength="12000" spellcheck="false">{esc(t['doc_example'])}</textarea></label><button type="button" class="button" id="doc-analyze">{e('doc_analyze')} ↗</button></div><div class="doc-results"><dl id="doc-fields"></dl><p id="doc-total"></p><p id="doc-status" role="status">{e('doc_stale')}</p><button type="button" class="button" id="doc-approve" disabled>{e('doc_approve')} ✓</button><p class="play-note">{e('doc_note')}</p></div>'''
 return f'''<section id="lab" class="interactive-lab section" aria-labelledby="lab-title"><div class="shell"><div class="lab-intro"><div><p class="eyebrow">NOVALIS / INTERACTIVE LAB</p><h2 id="lab-title">{br('lab_title')}</h2></div><p>{e('lab_intro')}</p></div><div class="play-tabs" role="tablist" aria-label="Novalis Interactive Lab">{tabs}</div><div class="play-panel" role="tabpanel" id="play-panel-0" aria-labelledby="play-tab-0"><div class="play-stage"><div class="play-stage-top"><span>{e('lab_badge')}</span><span>{e('lab_local')}</span></div>{controls}<div class="play-mobile-score" aria-hidden="true"><span>{e("score")}</span><output id="play-mobile-score">— %</output></div><div class="play-tools" role="group" aria-label="{e('canvas_label')}">{tools}</div><p id="play-instruction">{e('lab_help')}</p>{maphtml}{actions}</div><aside class="play-dashboard">{scientific}</aside><div class="play-panel-footer"><p>{e('lab_truth')}</p><details><summary>kNN / {e('explain')}</summary><p>{e('lab_method')}</p></details></div></div><div class="play-panel secondary-play" role="tabpanel" id="play-panel-1" aria-labelledby="play-tab-1" hidden>{optimize}</div><div class="play-panel secondary-play" role="tabpanel" id="play-panel-2" aria-labelledby="play-tab-2" hidden>{document}</div><noscript><p>{e('fallback')} {e('lab_method')}</p></noscript></div></section>'''
def method(t):
 buttons=''.join(f'<button type="button" data-method-phase="{i}" aria-pressed="{str(i==0).lower()}"><span>0{i+1}</span>{esc(v)}</button>' for i,v in enumerate(t['method_phases']))
 fallback=''.join(f'<details><summary>0{i+1} / {esc(v)}</summary><p>{esc(t["method_details"][i])}</p><p>{esc(t["deliverable"])} : {esc(t["method_deliverables"][i])}</p></details>' for i,v in enumerate(t['method_phases']))
 return f'<section id="methode" class="engineering-method section shell" aria-labelledby="method-title"><div class="section-heading"><div><p class="eyebrow">NOVALIS / DELIVERY</p><h2 id="method-title">{esc(t["method_title"]).replace(chr(10),"<br>")}</h2></div><p class="section-copy">{esc(t["method_copy"])}</p></div><div class="method-interactive"><div class="phase-selector" role="group" aria-label="{esc(t["method_title"])}">{buttons}</div><div class="phase-paper"><span class="paper-number" id="method-number">01</span><h3 id="method-name">{esc(t["method_phases"][0])}</h3><p id="method-detail">{esc(t["method_details"][0])}</p><div class="phase-deliverable"><span>{esc(t["deliverable"])}</span><strong id="method-deliverable">{esc(t["method_deliverables"][0])}</strong></div><div class="phase-decision"><span>{esc(t["decision"])}</span><p id="method-decision">{esc(t["method_decisions"][0])}</p></div></div></div><noscript>{fallback}</noscript></section>'
def crew(t):
 cards=[]
 for i in range(6):
  number=[TEAM['frontend']['count'],TEAM['backend']['count'],None,None,None,None][i]
  mark=f'<strong class="crew-count">{number:02d}</strong>' if number else f'<span class="crew-symbol" aria-hidden="true">{["","","⌁","◈","AS","↗"][i]}</span>'
  availability=t['crew_full'] if i<2 else t['crew_unknown'] if i<4 else 'Achraf Saidi / CTO' if i==4 else t['crew_network']
  cards.append(f'<article class="crew-role">{mark}<span class="crew-availability">{esc(availability)}</span><h3>{esc(t["crew_roles"][i])}</h3><p>{esc(t["crew_descriptions"][i])}</p></article>')
 stages=''.join(f'<button type="button" data-crew-stage="{i}" aria-pressed="{str(i==0).lower()}"><span>0{i+1}</span>{esc(v)}</button>' for i,v in enumerate(t['crew_stages']))
 return f'<section id="equipe" class="crew-section section shell" aria-labelledby="team-title"><div class="section-heading"><div><p class="eyebrow">NOVALIS / COLLECTIVE</p><h2 id="team-title">{esc(t["crew_title"]).replace(chr(10),"<br>")}</h2></div><p class="section-copy">{esc(t["crew_copy"])}</p></div><div class="crew-grid">'+''.join(cards)+f'</div><p class="crew-source">{esc(t["crew_source"])}</p><div class="crew-process"><h3>{esc(t["crew_roles_label"])}</h3><div role="group" aria-label="{esc(t["crew_roles_label"])}">{stages}</div><p id="crew-handoff" role="status">{esc(t["crew_handoffs"][0])}</p></div></section>'
def cases(t,lang,prefix):
 cards=[]
 for i,title in enumerate(t['case_titles']):
  image=ROOT/'assets'/f'case-{SLUGS[i]}.jpg'
  visual=f'<img src="{prefix}assets/{image.name}" width="1348" height="920" loading="lazy" alt="{esc(title)}">' if image.is_file() else f'<div class="case-diagram case-diagram-{i}" aria-hidden="true"><span>{title}</span><div><i>01</i><i>02</i><i>03</i></div><b>{["CRM → PROJECT → DELIVERY","ATLAS → EXPLORE → ITINERARY","QUESTION → HINT → UNDERSTAND"][i]}</b></div>'
  cards.append(f'<article class="case-card"><a class="case-cover" href="{prefix}{lang}/realisations/{SLUGS[i]}/">{visual}</a><div class="case-card-content"><span class="case-state">{esc(t["case_status"][i])}</span><h3>{esc(title)}</h3><p>{esc(t["case_summaries"][i])}</p><a class="text-link" href="{prefix}{lang}/realisations/{SLUGS[i]}/">{esc(t["case_more"])} ↗</a></div></article>')
 return f'<section id="realisations" class="case-section section shell" aria-labelledby="cases-title"><div class="section-heading"><div><p class="eyebrow">NOVALIS / IN PRACTICE</p><h2 id="cases-title">{esc(t["cases_title"]).replace(chr(10),"<br>")}</h2></div><p class="section-copy">{esc(t["cases_copy"])}</p></div><div class="case-grid">'+''.join(cards)+f'</div><p class="quiet-note">{esc(t["case_note"])}</p></section>'
def enrich_ultimate(lang,prefix,out,client):
 t=D[lang]
 out['ultimate_calendar']=f'<a class="button" href="https://www.cal.eu/novalisai/30min" target="_blank" rel="noopener noreferrer">{esc(t["calendar_cta"])} ↗</a><p class="booking-note">{esc(t["calendar_note"])}</p>'
 out.update(studio_hero=graph(t),ultimate_lab=lab(t),ultimate_method=method(t),ultimate_team=crew(t),ultimate_cases=cases(t,lang,prefix),ultimate_hero_cta=esc(t['hero_cta']),ultimate_hero_second=esc(t['hero_second']))
 out['ultimate_style_version']=version('ultimate.css');out['ultimate_script_version']=version('ultimate.js');out['lab_engine_version']=version('lab-engine.js')
 context=f'<div class="discovery-context"><h3>{esc(t["context_title"])}</h3><div class="context-grid"><label for="context-sector">{esc(t["context_labels"][0])}<select id="context-sector">{options(t["sectors"])}</select></label><label for="context-size">{esc(t["context_labels"][1])}<select id="context-size">{options(t["sizes"])}</select></label><label class="context-wide" for="context-tools">{esc(t["context_labels"][2])}<input id="context-tools" maxlength="180" placeholder="{esc(t["tools_placeholder"])}"></label><label for="context-priority">{esc(t["context_labels"][3])}<select id="context-priority">{options(t["project_priorities"])}</select></label><label for="context-budget">{esc(t["context_labels"][5])}<select id="context-budget">{options(t["budget_options"])}</select></label></div><fieldset class="context-constraints"><legend>{esc(t["context_labels"][4])}</legend>'+''.join(f'<label><input type="checkbox" data-context-constraint="{i}">{esc(v)}</label>' for i,v in enumerate(t['constraints']))+'</fieldset></div>'
 out['studio_explorer']=out['studio_explorer'].replace('<div class="studio-grid">',context+'<div class="studio-grid">')
 plan=f'<div class="architecture-plan"><h4>{esc(t["plan_title"])}</h4><ol>'+''.join(f'<li>{esc(v)}</li>' for v in t['plan_steps'])+f'</ol><p>{esc(t["brief_disclaimer"])}</p></div>'
 out['studio_explorer']=out['studio_explorer'].replace('<div class="estimate-grid">',plan+'<div class="estimate-grid">').replace('<p class="architecture-base">','<p id="architecture-context" class="architecture-base" role="status"></p><p class="architecture-base">')
 before=f'<div class="before-paper"><h3>{esc(t["before_title"])}</h3><p>'+esc(t['before_copy']).replace('\n','<br>')+'</p></div>'
 inventory=f'<div class="inventory-proof"><h4>{esc(t["after_title"])}</h4><span>{esc(t["stock_label"])} : <strong id="order-stock">12</strong></span><br><span>{esc(t["orders_label"])} : <strong id="order-count">0</strong></span><p>{esc(t["stock_note"])}</p></div>'
 out['studio_proof']=out['studio_proof'].replace('<ol class="order-steps">',before+'<ol class="order-steps">').replace('<div class="order-total">',inventory+'<div class="order-total">')
 client['ultimate']=t

def write_ultimate_pages(content,url):
 urls=[]
 for lang,t in D.items():
  for i,slug in enumerate(SLUGS[:1]):
   root=ROOT/lang/'realisations'/slug;root.mkdir(parents=True,exist_ok=True);canonical=f'{url}/{lang}/realisations/{slug}/'
   fields=['case_context','case_goals','case_users','case_features','case_arch','case_limits']
   blocks=''.join(f'<section><h2>{esc(t["case_labels"][n])}</h2><p>{esc(t[key][i])}</p></section>' for n,key in enumerate(fields))
   links=f'<a class="button" href="https://achraf-saidi.github.io/{slug}/" target="_blank" rel="noopener noreferrer">{esc(t["case_demo"])} ↗</a>' if i else f'<a class="text-link" href="https://app.novalisai.com/os/">{esc(t["case_login"])} ↗</a>'
   image=ROOT/'assets'/f'case-{slug}.jpg'
   visual=f'<figure><img src="../../../assets/{image.name}" alt="{esc(t["case_titles"][i])}" width="1348" height="926" loading="lazy"><figcaption>{esc(t["case_titles"][i])} · {esc(t["case_status"][i])} · {esc(t["case_demo"])}</figcaption></figure>' if image.is_file() else ''
   body=f'<main id="main" class="shell case-detail"><p class="eyebrow">NOVALIS / INTERNAL PROJECT</p><h1>{esc(t["case_titles"][i])}</h1><p class="case-detail-lead">{esc(t["case_summaries"][i])}</p><span class="case-state">{esc(t["case_status"][i])}</span>{visual}<div class="case-detail-body">{blocks}</div>{links}<p class="quiet-note">{esc(t["case_note"])}</p><a class="button" href="../../#contact">{esc(t["hero_cta"])} ↗</a></main>'
   (root/'index.html').write_text(page_shell(lang,canonical,t['case_titles'][i],body,{},'../../../',url,f'<a href="../../">{esc(t["case_more"])} ←</a>'));urls.append(canonical)
 return urls

def page_shell(lang,canonical,title,body,client,prefix,url,navigation):
 alternates=''.join(f'<link rel="alternate" hreflang="{l}" href="{canonical.replace("/"+lang+"/","/"+l+"/",1)}">' for l in D)
 data=json.dumps(client,ensure_ascii=False).replace('<','\\u003c')
 script=f'<script src="{prefix}assets/lab-engine.js?v={version("lab-engine.js")}" defer></script><script src="{prefix}assets/ultimate.js?v={version("ultimate.js")}" defer></script>' if client else ''
 return f'<!doctype html><html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{esc(title)} — Novalis AI"><title>{esc(title)} — Novalis AI</title><link rel="canonical" href="{canonical}">{alternates}<link rel="icon" href="{prefix}assets/N_novalis.png"><link rel="stylesheet" href="{prefix}assets/showcase.css?v={version("showcase.css")}">{script}<meta property="og:image" content="{url}/assets/novalis_og.png"><meta property="og:title" content="{esc(title)} — Novalis AI"><meta property="og:type" content="website"><meta property="og:url" content="{canonical}"></head><body class="ultimate-detail"><header class="site-header"><div class="shell header-inner"><a class="brand" href="{prefix}{lang}/"><img src="{prefix}assets/logo.webp" alt="Novalis AI" width="1200" height="269"></a>{navigation}<nav class="detail-language">'+''.join(f'<a href="{canonical.replace("/"+lang+"/","/"+l+"/",1)}" lang="{l}" hreflang="{l}">{l.upper()}</a>' for l in D)+f'</nav></div></header>{body}<footer class="detail-footer shell"><a href="mailto:contact@novalisai.com">contact@novalisai.com</a><span>Novalis AI · Wavre · BE 0878.868.302</span></footer><script id="site-data" type="application/json">{data}</script></body></html>'
